#[test]
fn sweep_every_reachable_mutation_is_idempotent_under_one_key() {
    let unequal: Vec<&str> = results.iter().filter(|r| !r.outcome_equal).collect();
    assert!(unequal.is_empty());
}

#[test]
fn sweep_one_key_with_a_different_request_is_refused_and_changes_nothing() {
    assert_eq!(clash.error_code(), Some(ErrorCode::IdempotencyKeyReused));
}
